import React, { useEffect, useRef } from "react";

// Running lion silhouette keypoints (normalized 0-1)
const LION_POINTS = [
  // Head/face core
  [0.72,0.14],[0.76,0.12],[0.79,0.14],[0.81,0.18],[0.80,0.23],
  [0.76,0.27],[0.71,0.28],[0.67,0.25],[0.65,0.20],[0.67,0.15],
  // Outer mane
  [0.70,0.07],[0.76,0.06],[0.82,0.08],[0.86,0.13],[0.87,0.20],
  [0.84,0.28],[0.79,0.33],[0.72,0.35],[0.64,0.33],[0.60,0.27],
  [0.59,0.20],[0.62,0.13],[0.67,0.09],
  // Body top
  [0.72,0.35],[0.62,0.36],[0.52,0.34],[0.42,0.32],[0.32,0.31],[0.22,0.33],[0.14,0.36],
  // Body bottom
  [0.14,0.44],[0.22,0.46],[0.32,0.44],[0.42,0.42],[0.52,0.42],[0.62,0.42],[0.72,0.41],
  // Front right leg
  [0.62,0.42],[0.61,0.52],[0.60,0.62],[0.58,0.72],[0.56,0.79],
  // Front left leg
  [0.52,0.42],[0.50,0.52],[0.49,0.62],[0.48,0.72],[0.46,0.79],
  // Back right leg
  [0.28,0.44],[0.30,0.55],[0.32,0.65],[0.34,0.72],[0.33,0.79],
  // Back left leg
  [0.20,0.44],[0.18,0.54],[0.16,0.64],[0.14,0.72],[0.13,0.79],
  // Tail curve
  [0.14,0.36],[0.09,0.32],[0.05,0.26],[0.05,0.18],[0.09,0.11],[0.12,0.07],
  // Eyes
  [0.70,0.20],[0.72,0.19],[0.74,0.20],[0.77,0.19],[0.79,0.20],[0.77,0.22],
  // Nose/mouth
  [0.73,0.25],[0.74,0.26],[0.76,0.25],
];

const LionCanvas = () => {
  const ref = useRef(null);

  useEffect(() => {
    const canvas = ref.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");

    const resize = () => {
      canvas.width = canvas.offsetWidth;
      canvas.height = canvas.offsetHeight;
    };
    resize();
    window.addEventListener("resize", resize, { passive: true });

    // Build particles from lion points
    const makeParticle = ([nx, ny]) => ({
      x: nx * canvas.width + (Math.random() - 0.5) * 60,
      y: ny * canvas.height + (Math.random() - 0.5) * 60,
      tx: nx * canvas.width,
      ty: ny * canvas.height,
      r: 1 + Math.random() * 2.5,
      alpha: 0.35 + Math.random() * 0.45,
      hue: 32 + Math.random() * 28,
      phase: Math.random() * Math.PI * 2,
      speed: 0.015 + Math.random() * 0.025,
      idx: Math.random(),
    });

    let particles = LION_POINTS.map(makeParticle);

    // Add dust/glow scatter around mane
    for (let i = 0; i < 100; i++) {
      const base = LION_POINTS[Math.floor(Math.random() * 22)]; // mane region
      particles.push({
        x: base[0] * canvas.width + (Math.random() - 0.5) * 100,
        y: base[1] * canvas.height + (Math.random() - 0.5) * 100,
        tx: base[0] * canvas.width,
        ty: base[1] * canvas.height,
        r: 0.5 + Math.random() * 1.5,
        alpha: 0.08 + Math.random() * 0.18,
        hue: 38 + Math.random() * 20,
        phase: Math.random() * Math.PI * 2,
        speed: 0.008 + Math.random() * 0.015,
        idx: Math.random(),
      });
    }

    let raf;
    let t = 0;

    const draw = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      t += 0.008;

      // Draw subtle connection lines
      for (let i = 0; i < LION_POINTS.length - 1; i++) {
        const a = particles[i], b = particles[i + 1];
        const d = Math.hypot(a.tx - b.tx, a.ty - b.ty);
        if (d < 70) {
          ctx.beginPath();
          ctx.moveTo(a.x, a.y);
          ctx.lineTo(b.x, b.y);
          ctx.strokeStyle = `hsla(42,80%,55%,${0.06 * (1 - d / 70)})`;
          ctx.lineWidth = 0.6;
          ctx.stroke();
        }
      }

      particles.forEach((p, i) => {
        p.phase += p.speed;
        const pulse = 0.5 + 0.5 * Math.sin(p.phase);
        // Drift gently toward target
        p.x += (p.tx - p.x) * 0.012 + Math.sin(t + p.idx * 6.28) * 0.4;
        p.y += (p.ty - p.y) * 0.012 + Math.cos(t + p.idx * 6.28) * 0.4;

        const sz = p.r * (0.7 + 0.6 * pulse);
        const al = p.alpha * (0.6 + 0.4 * pulse);

        // Outer glow
        const g = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, sz * 5);
        g.addColorStop(0, `hsla(${p.hue},90%,68%,${al})`);
        g.addColorStop(1, `hsla(${p.hue},90%,55%,0)`);
        ctx.beginPath();
        ctx.arc(p.x, p.y, sz * 5, 0, Math.PI * 2);
        ctx.fillStyle = g;
        ctx.fill();

        // Core dot
        ctx.beginPath();
        ctx.arc(p.x, p.y, sz, 0, Math.PI * 2);
        ctx.fillStyle = `hsla(${p.hue},95%,82%,${al + 0.15})`;
        ctx.fill();
      });

      raf = requestAnimationFrame(draw);
    };

    draw();
    return () => {
      cancelAnimationFrame(raf);
      window.removeEventListener("resize", resize);
    };
  }, []);

  return (
    <canvas
      ref={ref}
      style={{
        position: "absolute",
        inset: 0,
        width: "100%",
        height: "100%",
        pointerEvents: "none",
        opacity: 0.22,
      }}
    />
  );
};

export default LionCanvas;
