// ============================================================
// IMPROVED MATCHING ALGORITHM
// ============================================================
const GREETING_WORDS = new Set(["hi", "hey", "hello", "greetings", "sup", "howdy", "yo"]);
const MIN_WORD_LEN = 3;

const getResponse = (input) => {
  const norm = normalize(input);

  // Fast path: explicit greeting detection before anything else
  const rawWords = norm.split(/\s+/);
  if (rawWords.some((w) => GREETING_WORDS.has(w))) {
    return intents.find((i) => i.tag === "greeting").response();
  }

  // Filter out very short words that cause false positives
  const words = rawWords.filter((w) => w.length >= MIN_WORD_LEN);
  if (words.length === 0) {
    return fallbackResponses[0];
  }

  let bestMatch = null;
  let bestScore = 0;

  for (const intent of intents) {
    for (const pattern of intent.patterns) {
      const patternWords = normalize(pattern)
        .split(/\s+/)
        .filter((p) => p.length >= MIN_WORD_LEN);

      if (patternWords.length === 0) continue;

      // Count matches: exact word equality OR prefix match for long words (5+ chars)
      const matchedCount = patternWords.filter((pw) =>
        words.some(
          (w) =>
            w === pw ||
            (pw.length >= 5 && (w.startsWith(pw) || pw.startsWith(w)))
        )
      ).length;

      // Proportional score: fraction of pattern words that matched
      const score = matchedCount / patternWords.length;

      if (score > bestScore) {
        bestScore = score;
        bestMatch = intent;
      }
    }
  }

  // Require at least 50% of pattern words to match to avoid false positives
  if (bestScore >= 0.5 && bestMatch) return bestMatch.response();
  return fallbackResponses[Math.floor(Math.random() * fallbackResponses.length)];
};

