/* ── 3D Tilt Card ── */
const TiltCard = ({ children, className, onClick, style }) => {
  const ref = useRef(null);
  const xRaw = useMotionValue(0);
  const yRaw = useMotionValue(0);
  const x = useSpring(xRaw, { stiffness: 200, damping: 20 });
  const y = useSpring(yRaw, { stiffness: 200, damping: 20 });
  const rotateX = useTransform(y, [-80, 80], [8, -8]);
  const rotateY = useTransform(x, [-80, 80], [-8, 8]);

  const handleMouse = (e) => {
    if (!ref.current) return;
    const rect = ref.current.getBoundingClientRect();
    xRaw.set(e.clientX - rect.left - rect.width / 2);
    yRaw.set(e.clientY - rect.top - rect.height / 2);
  };

  const handleLeave = () => { xRaw.set(0); yRaw.set(0); };

  return (
    <motion.div
      ref={ref}
      className={className}
      style={{ rotateX, rotateY, transformStyle: "preserve-3d", ...style }}
      onMouseMove={handleMouse}
      onMouseLeave={handleLeave}
      onClick={onClick}
    >
      {children}
    </motion.div>
  );
};

