import React from "react";
import "./skills-ticker.css";

const ROWS = [
  ["Python", "LangChain", "BERT", "RoBERTa", "TensorFlow", "PyTorch", "FAISS", "RAG", "LoRA", "PEFT", "Transformers", "AWS SageMaker"],
  ["React", "Node.js", "TypeScript", "Spring Boot", "PostgreSQL", "Docker", "Kubernetes", "MLflow", "Azure ML", "GCP AI"],
  ["Scikit-learn", "XGBoost", "LightGBM", "spaCy", "Hugging Face", "NLP", "Intent Classification", "Sentiment Analysis", "NER", "SHAP", "MLOps", "CI/CD"],
];

const DIRECTIONS = ["left", "right", "left"];

const SkillsTicker = () => (
  <div className="ticker__container" aria-hidden="true">
    {ROWS.map((row, ri) => (
      <div key={ri} className={`ticker__row ticker__row--${DIRECTIONS[ri]}`}>
        <div className={`ticker__track ticker__track--${DIRECTIONS[ri]}`}>
          {[...row, ...row].map((skill, i) => (
            <span key={i} className="ticker__item">
              <span className="ticker__dot" />
              {skill}
            </span>
          ))}
        </div>
      </div>
    ))}
  </div>
);

export default SkillsTicker;
