import React, { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { Github, Linkedin, Mail, Download, ArrowRight, Zap, ExternalLink } from "lucide-react";
import CV from "../../assets/Resume.pdf";
import LionCanvas from "../canvas/LionCanvas";
import SkillsTicker from "../canvas/SkillsTicker";
import "./home.css";

const ROLES = [
  "Applied AI Engineer",
  "NLP & LLM Fine-Tuning",
  "Full Stack Developer",
  "MLOps Engineer",
  "AI Systems Builder",
];

const STATS = [
  { value: "4+", label: "Years Experience", icon: "⚡" },
  { value: "15+", label: "Projects Delivered", icon: "🚀" },
  { value: "4+", label: "AI Solutions Built", icon: "🤖" },
  { value: "4+", label: "Teams Led", icon: "🏆" },
];

const CURRENT_PROJECT = {
  name: "DriveAssist-AI",
  description: "AI-powered RAG Knowledge Assistant providing real-time contextual driving guidance using LangChain, FAISS vector store, and AWS Lambda.",
  tech: ["Python", "LangChain", "FAISS", "RAG", "AWS Lambda"],
  github: "https://github.com/BhaskarTheCoder/DriveAssist-AI",
  status: "active",
};

const Home = () => {
  const [roleIdx, setRoleIdx] = useState(0);
  const [displayed, setDisplayed] = useState("");
  const [typing, setTyping] = useState(true);

  useEffect(() => {
    const current = ROLES[roleIdx];
    let t;
    if (typing) {
      if (displayed.length < current.length) {
        t = setTimeout(() => setDisplayed(current.slice(0, displayed.length + 1)), 65);
      } else {
        t = setTimeout(() => setTyping(false), 2200);
      }
    } else {
      if (displayed.length > 0) {
        t = setTimeout(() => setDisplayed(displayed.slice(0, -1)), 35);
      } else {
        setRoleIdx(i => (i + 1) % ROLES.length);
        setTyping(true);
      }
    }
    return () => clearTimeout(t);
  }, [displayed, typing, roleIdx]);

  const cv = { stagger: { staggerChildren: 0.12, delayChildren: 0.3 } };
  const item = { hidden: { opacity: 0, y: 24 }, visible: { opacity: 1, y: 0, transition: { duration: 0.55, ease: "easeOut" } } };

  return (
    <section className="home section" id="home">
      {/* ── Backgrounds ── */}
      <LionCanvas />
      <SkillsTicker />
      <div className="home__grid-dots" aria-hidden="true" />

      <div className="home__container container">

        {/* ── LEFT COLUMN: Hero Text ── */}
        <motion.div className="home__hero" initial="hidden" animate="visible" variants={cv}>

          {/* Badge */}
          <motion.div variants={item} className="home__badge">
            <span className="home__badge-dot" />
            Open to Full-Time AI/ML Roles · Dallas, TX
          </motion.div>

          {/* Name */}
          <motion.h1 variants={item} className="home__name">
            Uday Bhaskar<br />
            <span className="home__name-gradient">Valapadasu</span>
          </motion.h1>

          {/* Typing role */}
          <motion.div variants={item} className="home__role">
            <span className="home__role-bracket">&lt;</span>
            <span className="home__role-text">{displayed}</span>
            <span className="home__cursor" />
            <span className="home__role-bracket">/&gt;</span>
          </motion.div>

          {/* Intro */}
          <motion.p variants={item} className="home__intro">
            AI/ML Engineer with 4+ years building production-grade NLP &amp; Deep Learning systems.
            Fine-tuning LLMs, deploying RAG pipelines, and shipping agentic AI at enterprise scale.
          </motion.p>

          {/* CTAs */}
          <motion.div variants={item} className="home__actions">
            <a href="#contact" className="btn btn-primary">
              Hire Me <ArrowRight size={16} />
            </a>
            <a href={CV} download className="btn btn-outline">
              <Download size={15} /> Resume
            </a>
          </motion.div>

          {/* Socials */}
          <motion.div variants={item} className="home__socials">
            <a href="https://github.com/BhaskarTheCoder" target="_blank" rel="noreferrer" className="home__social" aria-label="GitHub">
              <Github size={18} />
            </a>
            <a href="https://www.linkedin.com/in/vub21" target="_blank" rel="noreferrer" className="home__social" aria-label="LinkedIn">
              <Linkedin size={18} />
            </a>
            <a href="mailto:uday.valapadasu8167@gmail.com" className="home__social" aria-label="Email">
              <Mail size={18} />
            </a>
          </motion.div>

          {/* More projects link */}
          <motion.div variants={item} className="home__more-projects">
            <a href="#portfolio" className="home__projects-link">
              View All Projects <ArrowRight size={14} />
            </a>
          </motion.div>
        </motion.div>

        {/* ── RIGHT COLUMN: Stats + Current Project ── */}
        <div className="home__right">

          {/* Stats */}
          <motion.div
            className="home__stats"
            initial={{ opacity: 0, y: 30 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.8, duration: 0.6 }}
          >
            {STATS.map(s => (
              <div key={s.label} className="home__stat">
                <div className="home__stat-icon">{s.icon}</div>
                <div className="home__stat-value">{s.value}</div>
                <div className="home__stat-label">{s.label}</div>
              </div>
            ))}
          </motion.div>

          {/* Current Project */}
          <motion.div
            className="home__current"
            initial={{ opacity: 0, y: 30 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 1.0, duration: 0.6 }}
          >
            <div className="home__current-header">
              <div className="home__current-live">
                <span className="home__live-dot" />
                Featured Project
              </div>
              <a href={CURRENT_PROJECT.github} target="_blank" rel="noreferrer" className="home__current-link">
                <ExternalLink size={13} /> GitHub
              </a>
            </div>
            <div className="home__current-content">
              <div className="home__current-icon"><Zap size={20} /></div>
              <div>
                <div className="home__current-name">{CURRENT_PROJECT.name}</div>
                <p className="home__current-desc">{CURRENT_PROJECT.description}</p>
                <div className="home__current-tech">
                  {CURRENT_PROJECT.tech.map(t => (
                    <span key={t} className="home__tech-tag">{t}</span>
                  ))}
                </div>
              </div>
            </div>
          </motion.div>

        </div>
      </div>

      {/* Scroll hint */}
      <motion.a
        href="#about"
        className="home__scroll"
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ delay: 1.6 }}
      >
        <motion.div animate={{ y: [0, 8, 0] }} transition={{ duration: 1.6, repeat: Infinity }}>↓</motion.div>
      </motion.a>
    </section>
  );
};

export default Home;
