const ExperienceCard = ({ exp, index, inView }) => {
  const [open, setOpen] = useState(index === 0);

  return (
    <motion.div
      className={`exp__card ${exp.current ? "exp__card--current" : ""}`}
      initial={{ opacity: 0, x: -30 }}
      animate={inView ? { opacity: 1, x: 0 } : {}}
      transition={{ duration: 0.55, delay: index * 0.1 }}
    >
      {/* Timeline dot */}
      <div className="exp__dot" style={{ background: exp.color, boxShadow: `0 0 12px ${exp.color}66` }}>
        <Briefcase size={12} />
      </div>

      <div className="exp__card-inner glass-card">
        {/* Header row */}
        <div className="exp__header" onClick={() => setOpen(!open)} role="button" tabIndex={0} onKeyDown={e => e.key === "Enter" && setOpen(!open)}>
          <div className="exp__header-left">
            <div className="exp__title-row">
              <h3 className="exp__title">{exp.title}</h3>
              {exp.current && (
                <span className="exp__current-badge">
                  <span className="exp__live-dot" style={{ background: exp.color }} />
                  Current
                </span>
              )}
              <span className="exp__type">{exp.type}</span>
            </div>
            <div className="exp__company">{exp.company}</div>
            <div className="exp__meta">
              <span><Calendar size={12} />{exp.period}</span>
              <span><MapPin size={12} />{exp.location}</span>
              <span className="exp__duration">{exp.duration}</span>
            </div>
          </div>
          <button className="exp__toggle" aria-label="Toggle details">
            {open ? <ChevronUp size={18} /> : <ChevronDown size={18} />}
          </button>
        </div>

        {/* Expanded content */}
        <motion.div
          className="exp__body"
          initial={false}
          animate={{ height: open ? "auto" : 0, opacity: open ? 1 : 0 }}
          transition={{ duration: 0.3 }}
          style={{ overflow: "hidden" }}
        >
          <div className="exp__client">
            <ExternalLink size={12} /> {exp.client}
          </div>

          <ul className="exp__bullets">
            {exp.bullets.map((b, i) => (
              <li key={i} className="exp__bullet">
                <span className="exp__bullet-dot" style={{ background: exp.color }} />
                {b}
              </li>
            ))}
          </ul>

          <div className="exp__tags">
            {exp.tags.map(t => (
              <span key={t} className="exp__tag" style={{ borderColor: `${exp.color}44`, color: exp.color }}>
                {t}
              </span>
            ))}
          </div>
        </motion.div>
      </div>
    </motion.div>
  );
};

